with content as (
 select * from jsonb_to_recordset($content$[
  {"level":"A1","title":"My Future Plan","body":"Naomi thinks about her future. She wants to finish school, learn English and work in a hotel. She likes helping people and speaking with visitors.\n\nShe draws three pictures on a page. The first picture shows her school books. The second shows an English class. The third shows Naomi in a hotel.\n\nUnder each picture, she writes one action. For school, she writes, \"Do my homework.\" For English, she writes, \"Practise for ten minutes every day.\" For the hotel, she writes, \"Learn how to welcome a visitor.\"\n\nNaomi puts the page on her wall. Every Sunday, she looks at it. She puts a small mark next to the actions she has done.\n\nSome weeks are difficult, and Naomi does not do everything. She looks at the page and starts again. She cannot know every part of her future, but she can choose useful actions today. Her plan gives her a direction.","summary_fr":"Naomi dessine son avenir : école, anglais et travail dans un hôtel. Elle associe une action à chaque image et suit ses efforts chaque dimanche.","translation_fr":"Naomi pense à son avenir. Elle veut terminer l'école, apprendre l'anglais et travailler dans un hôtel. Elle aime aider les gens et parler avec les visiteurs.\n\nElle dessine trois images sur une page. La première montre ses livres scolaires. La deuxième montre un cours d'anglais. La troisième montre Naomi dans un hôtel.\n\nSous chaque image, elle écrit une action. Pour l'école, elle écrit : « Faire mes devoirs. » Pour l'anglais, elle écrit : « M'entraîner dix minutes chaque jour. » Pour l'hôtel, elle écrit : « Apprendre à accueillir un visiteur. »\n\nNaomi met la page sur son mur. Chaque dimanche, elle la regarde. Elle met une petite marque à côté des actions réalisées.\n\nCertaines semaines sont difficiles et Naomi ne fait pas tout. Elle regarde la page et recommence. Elle ne peut pas connaître chaque partie de son avenir, mais elle peut choisir des actions utiles aujourd'hui. Son plan lui donne une direction.","knowledge_point":"L'apprenant relie une vision simple de l'avenir à des actions quotidiennes et à un suivi hebdomadaire.","vocabulary":[{"word":"future","part_of_speech":"noun","translation_fr":"avenir","definition":"The time after now.","example":"Naomi thinks about her future."},{"word":"hotel","part_of_speech":"noun","translation_fr":"hôtel","definition":"A place where visitors pay to stay.","example":"She wants to work in a hotel."},{"word":"visitor","part_of_speech":"noun","translation_fr":"visiteur","definition":"A person visiting a place.","example":"She speaks with visitors."},{"word":"draw","part_of_speech":"verb","translation_fr":"dessiner","definition":"To make a picture with a pen or pencil.","example":"She draws three pictures."},{"word":"welcome","part_of_speech":"verb","translation_fr":"accueillir","definition":"To greet someone in a friendly way.","example":"She learns to welcome a visitor."},{"word":"wall","part_of_speech":"noun","translation_fr":"mur","definition":"The side of a room or building.","example":"The page is on her wall."},{"word":"mark","part_of_speech":"noun","translation_fr":"marque","definition":"A small sign showing information.","example":"She puts a mark next to the action."},{"word":"direction","part_of_speech":"noun","translation_fr":"direction","definition":"The way towards a goal.","example":"Her plan gives her a direction."}],"questions":[{"type":"mcq","question":"Where does Naomi want to work?","options":["In a hotel","In a shop","In a hospital","On a farm"],"answer":"In a hotel","explanation_fr":"Elle veut travailler dans un hôtel."},{"type":"mcq","question":"Why does she like this idea?","options":["She likes helping people and speaking with visitors","She likes sleeping late","She dislikes English","She wants to stop school"],"answer":"She likes helping people and speaking with visitors","explanation_fr":"Ces deux goûts motivent son projet."},{"type":"mcq","question":"How many pictures does she draw?","options":["Three","Two","Four","Five"],"answer":"Three","explanation_fr":"Elle dessine trois images."},{"type":"mcq","question":"What is her action for school?","options":["Do her homework","Buy a hotel","Welcome visitors","Draw every day"],"answer":"Do her homework","explanation_fr":"Elle associe les devoirs à l'école."},{"type":"mcq","question":"How long does she practise English?","options":["Ten minutes every day","One hour on Sunday","Two minutes each month","Only during class"],"answer":"Ten minutes every day","explanation_fr":"Son action prévoit dix minutes quotidiennes."},{"type":"mcq","question":"When does she look at the page?","options":["Every Sunday","Every morning","Once a year","Only at school"],"answer":"Every Sunday","explanation_fr":"Elle examine son plan chaque dimanche."},{"type":"mcq","question":"What does she do after a difficult week?","options":["Starts again","Removes the page","Changes every dream","Stops all actions"],"answer":"Starts again","explanation_fr":"Elle reprend après une semaine difficile."},{"type":"true_false","question":"Naomi can know every part of her future.","options":["True","False"],"answer":"False","explanation_fr":"Le texte dit qu'elle ne peut pas tout connaître."},{"type":"true_false","question":"Her plan gives her a direction.","options":["True","False"],"answer":"True","explanation_fr":"C'est la dernière phrase du texte."},{"type":"open","question":"What picture and action could you put on your future plan?","options":[],"answer":"I can draw myself speaking English at work and write that I will practise for ten minutes every day.","explanation_fr":"La réponse doit relier une image du futur à une action présente."}],"grammar":[{"point":"Want to for future wishes","explanation_fr":"Want to suivi d'une base verbale exprime un projet.","example":"She wants to finish school."},{"point":"Present simple for repeated actions","explanation_fr":"Le présent simple décrit les actions habituelles du plan.","example":"She practises for ten minutes every day."}],"discussion":["What would you draw on your future plan?","Which action can you do today?","When will you review your plan?"]},
  {"level":"A2","title":"A Letter to My Future Self","body":"In class, Kevin's teacher asks everyone to write a letter to their future self. The letter will be opened in one year. Kevin sits quietly for a moment because he has never thought about his future in this way.\n\nHe begins with three hopes. He hopes to speak English with more confidence, pass his exams and help his younger sister with reading. Then he writes about the actions that could make these hopes real.\n\nFor English, he promises to join the school speaking club twice a week. For his exams, he plans to review each subject for a short time instead of waiting for the night before. For his sister, he chooses two evenings when they can read a story together.\n\nKevin also writes about possible difficulties. He may feel tired, miss a club meeting or need to help at home. He does not want one missed activity to make him abandon the whole plan. He writes, \"If you miss a day, begin again at the next opportunity.\"\n\nBefore closing the letter, Kevin adds a question: \"What have you learned, even if everything did not happen as planned?\" He understands that a future plan is not a promise that life will be perfect.\n\nThe letter gives him a clear direction for the year. It also reminds him to notice learning, effort and change, not only final results.","summary_fr":"Kevin écrit une lettre à son futur lui-même avec trois espoirs, des actions concrètes et une réponse aux imprévus. Il veut aussi évaluer ses apprentissages, pas seulement les résultats.","translation_fr":"En classe, le professeur de Kevin demande à chacun d'écrire une lettre à son futur soi-même. La lettre sera ouverte dans un an. Kevin reste silencieux un moment parce qu'il n'a jamais pensé à son avenir de cette façon.\n\nIl commence par trois espoirs. Il espère parler anglais avec plus de confiance, réussir ses examens et aider sa petite sœur à lire. Ensuite, il écrit les actions qui pourraient rendre ces espoirs réels.\n\nPour l'anglais, il promet de rejoindre le club d'expression orale de l'école deux fois par semaine. Pour ses examens, il prévoit de réviser chaque matière pendant une courte période au lieu d'attendre la veille. Pour sa sœur, il choisit deux soirées où ils peuvent lire une histoire ensemble.\n\nKevin écrit aussi sur les difficultés possibles. Il peut être fatigué, manquer une réunion du club ou devoir aider à la maison. Il ne veut pas qu'une activité manquée lui fasse abandonner tout le plan. Il écrit : « Si tu manques un jour, recommence à la prochaine occasion. »\n\nAvant de fermer la lettre, Kevin ajoute une question : « Qu'as-tu appris, même si tout ne s'est pas passé comme prévu ? » Il comprend qu'un plan d'avenir n'est pas une promesse que la vie sera parfaite.\n\nLa lettre lui donne une direction claire pour l'année. Elle lui rappelle aussi de remarquer les apprentissages, les efforts et les changements, pas seulement les résultats finaux.","knowledge_point":"L'apprenant écrit une vision à un an, associe des actions aux espoirs et prévoit une réponse constructive aux imprévus.","vocabulary":[{"word":"future self","part_of_speech":"noun phrase","translation_fr":"futur soi-même","definition":"The person you will become later.","example":"Kevin writes to his future self."},{"word":"hope","part_of_speech":"noun","translation_fr":"espoir","definition":"A feeling that something good can happen.","example":"He begins with three hopes."},{"word":"confidence","part_of_speech":"noun","translation_fr":"confiance","definition":"Belief in your ability to do something.","example":"He wants more confidence in English."},{"word":"pass","part_of_speech":"verb","translation_fr":"réussir","definition":"To reach the required standard in an exam.","example":"He hopes to pass his exams."},{"word":"promise","part_of_speech":"verb","translation_fr":"promettre","definition":"To say that you will certainly do something.","example":"He promises to join the club."},{"word":"opportunity","part_of_speech":"noun","translation_fr":"occasion","definition":"A suitable time to do something.","example":"Begin again at the next opportunity."},{"word":"abandon","part_of_speech":"verb","translation_fr":"abandonner","definition":"To stop before completing something.","example":"Do not abandon the whole plan."},{"word":"effort","part_of_speech":"noun","translation_fr":"effort","definition":"The energy used to achieve something.","example":"Notice effort as well as results."}],"questions":[{"type":"mcq","question":"When will Kevin open the letter?","options":["In one year","Next week","After ten years","At the end of class"],"answer":"In one year","explanation_fr":"La lettre sera ouverte dans un an."},{"type":"mcq","question":"How many hopes does he write first?","options":["Three","Two","Five","One"],"answer":"Three","explanation_fr":"Il commence par trois espoirs."},{"type":"mcq","question":"How often will he join the speaking club?","options":["Twice a week","Every day","Once a month","Only before exams"],"answer":"Twice a week","explanation_fr":"Il prévoit deux séances par semaine."},{"type":"mcq","question":"When will he review his school subjects?","options":["For a short time regularly","Only the night before","Only on Sunday morning","After the exams"],"answer":"For a short time regularly","explanation_fr":"Il veut éviter d'attendre la veille."},{"type":"mcq","question":"What will he do with his sister?","options":["Read a story together","Join a hotel","Write her exams","Teach a speaking club"],"answer":"Read a story together","explanation_fr":"Il choisit deux soirées de lecture commune."},{"type":"mcq","question":"What should he do after missing a day?","options":["Begin again at the next opportunity","Abandon the whole plan","Write no more letters","Wait for another year"],"answer":"Begin again at the next opportunity","explanation_fr":"C'est l'instruction écrite dans sa lettre."},{"type":"mcq","question":"What does his final question focus on?","options":["Learning even when plans change","Perfect results only","Other people's letters","Forgetting every difficulty"],"answer":"Learning even when plans change","explanation_fr":"Il veut reconnaître les apprentissages malgré les imprévus."},{"type":"true_false","question":"Kevin expects life to follow his plan perfectly.","options":["True","False"],"answer":"False","explanation_fr":"Il comprend qu'un plan n'est pas une promesse de perfection."},{"type":"true_false","question":"The letter connects hopes with actions.","options":["True","False"],"answer":"True","explanation_fr":"Chaque espoir est accompagné d'actions concrètes."},{"type":"open","question":"What would you write to your future self about one hope and one action?","options":[],"answer":"I hope to speak English confidently, so I will practise twice a week and begin again if I miss a session.","explanation_fr":"La réponse doit relier un espoir, une action et une reprise possible."}],"grammar":[{"point":"Will for future time","explanation_fr":"Will indique ici le moment futur où la lettre sera ouverte.","example":"The letter will be opened in one year."},{"point":"If for a possible difficulty","explanation_fr":"If suivi du présent simple décrit une situation possible et sa réponse.","example":"If you miss a day, begin again."}],"discussion":["What hope would you include in your letter?","Which difficulty should your plan anticipate?","What would you like to learn this year?"]},
  {"level":"B1","title":"A Future Built from Choices","body":"It is common to imagine the future as a single day when everything changes: the day you graduate, find a job or complete a major project. These moments matter, but they are usually prepared by many smaller choices that receive less attention.\n\nDesigning your future does not mean controlling every event. Health, family responsibilities, economic conditions and other people's decisions can affect your path. A useful plan recognises this uncertainty while identifying the areas where your choices still have influence.\n\nBegin with a direction rather than a perfect description. Instead of saying exactly where you must be in ten years, ask what kind of work, relationships and daily life you want to move towards. Then identify the abilities, habits and connections that could support that direction.\n\nNext, look at your present routine. Your calendar shows what currently receives your time. If learning a valuable skill matters but never appears in your week, there is a difference between your stated goal and your actual choices. This is not a reason for shame. It is information that can guide a change.\n\nA future plan should also include other people. You may need a teacher, a colleague, a family member or a community group. Asking for guidance is not a lack of independence. It can help you avoid mistakes and discover opportunities that you would not find alone.\n\nFinally, review the plan at regular moments. A direction that suited you last year may need adjustment after a new experience. Changing the plan does not always mean failure. Sometimes it means that you have learned more about yourself and the world.\n\nYour future is not built only by big decisions. It is also shaped by repeated actions, the people you learn with and your willingness to revise. You cannot choose everything that happens, but you can choose what you practise, protect and pursue next.","summary_fr":"L'avenir se construit par des choix répétés dans un contexte incertain. Une direction, un calendrier réaliste, des relations d'appui et des révisions régulières permettent d'avancer sans prétendre tout contrôler.","translation_fr":"Il est courant d'imaginer l'avenir comme un jour unique où tout change : le jour de l'obtention du diplôme, de l'emploi ou de la réalisation d'un grand projet. Ces moments comptent, mais ils sont généralement préparés par de nombreux petits choix moins visibles.\n\nConcevoir votre avenir ne signifie pas contrôler chaque événement. La santé, les responsabilités familiales, les conditions économiques et les décisions des autres peuvent affecter votre parcours. Un plan utile reconnaît cette incertitude tout en identifiant les domaines où vos choix ont encore une influence.\n\nCommencez par une direction plutôt qu'une description parfaite. Au lieu de dire exactement où vous devez être dans dix ans, demandez quel type de travail, de relations et de vie quotidienne vous voulez approcher. Identifiez ensuite les capacités, habitudes et relations qui pourraient soutenir cette direction.\n\nPuis, regardez votre routine actuelle. Votre calendrier montre ce qui reçoit actuellement votre temps. Si apprendre une compétence précieuse compte mais n'apparaît jamais dans votre semaine, il existe une différence entre votre objectif déclaré et vos choix réels. Ce n'est pas une raison de honte. C'est une information qui peut guider un changement.\n\nUn plan d'avenir devrait aussi inclure d'autres personnes. Vous pouvez avoir besoin d'un professeur, d'un collègue, d'un membre de la famille ou d'un groupe communautaire. Demander de l'aide n'est pas un manque d'indépendance. Cela peut éviter des erreurs et révéler des occasions que vous ne trouveriez pas seul.\n\nEnfin, révisez le plan à des moments réguliers. Une direction qui vous convenait l'année dernière peut demander un ajustement après une nouvelle expérience. Changer le plan ne signifie pas toujours échouer. Cela signifie parfois que vous avez appris davantage sur vous-même et sur le monde.\n\nVotre avenir n'est pas construit seulement par de grandes décisions. Il est aussi formé par des actions répétées, les personnes avec qui vous apprenez et votre volonté de réviser. Vous ne pouvez pas choisir tout ce qui arrive, mais vous pouvez choisir ce que vous pratiquez, protégez et poursuivez ensuite.","knowledge_point":"L'apprenant construit une direction réaliste en reliant valeurs, emploi du temps, soutien humain et révision dans un environnement incertain.","vocabulary":[{"word":"graduate","part_of_speech":"verb","translation_fr":"obtenir un diplôme","definition":"To successfully complete a course of study.","example":"Graduation is one important day."},{"word":"uncertainty","part_of_speech":"noun","translation_fr":"incertitude","definition":"The state of not knowing what will happen.","example":"A useful plan recognises uncertainty."},{"word":"influence","part_of_speech":"noun","translation_fr":"influence","definition":"The power to affect something.","example":"Your choices still have influence."},{"word":"connection","part_of_speech":"noun","translation_fr":"relation","definition":"A useful relationship with another person or group.","example":"Connections can support your direction."},{"word":"stated","part_of_speech":"adjective","translation_fr":"déclaré","definition":"Expressed clearly in words.","example":"Compare your stated goal with your calendar."},{"word":"guidance","part_of_speech":"noun","translation_fr":"accompagnement","definition":"Helpful advice from someone.","example":"Ask for guidance."},{"word":"revise","part_of_speech":"verb","translation_fr":"réviser, réajuster","definition":"To change after reviewing.","example":"Revise the plan regularly."},{"word":"pursue","part_of_speech":"verb","translation_fr":"poursuivre","definition":"To work towards a goal.","example":"Choose what you pursue next."}],"questions":[{"type":"mcq","question":"What prepares many major future moments?","options":["Many smaller choices","One perfect description","Complete control of events","No regular action"],"answer":"Many smaller choices","explanation_fr":"Les grands moments sont souvent préparés par des choix moins visibles."},{"type":"mcq","question":"Which factor can affect your path?","options":["Economic conditions","Only your written plan","Only your preferred job","Nothing outside your control"],"answer":"Economic conditions","explanation_fr":"Le texte cite aussi la santé, la famille et les décisions des autres."},{"type":"mcq","question":"What is better than an exact ten-year description?","options":["A direction for work, relationships and daily life","A promise to control everything","A plan without habits","A list of final results only"],"answer":"A direction for work, relationships and daily life","explanation_fr":"Une direction permet de progresser sans prétendre tout prévoir."},{"type":"mcq","question":"What does your calendar reveal?","options":["What currently receives your time","Every future opportunity","Your final professional level","Other people's decisions"],"answer":"What currently receives your time","explanation_fr":"Le calendrier permet de comparer objectifs et choix réels."},{"type":"mcq","question":"How should you respond to a gap between goal and routine?","options":["Use it as information for change","Feel shame and stop planning","Ignore the calendar","Add more final goals"],"answer":"Use it as information for change","explanation_fr":"L'écart doit guider un ajustement, pas la honte."},{"type":"mcq","question":"Why include other people in a future plan?","options":["They can provide guidance and reveal opportunities","They can control every event","They remove the need for practice","They make revision unnecessary"],"answer":"They can provide guidance and reveal opportunities","explanation_fr":"Le soutien humain aide à éviter des erreurs et découvrir des possibilités."},{"type":"mcq","question":"What can changing a plan sometimes mean?","options":["You have learned more about yourself and the world","You have always failed","You have no direction","You must abandon every value"],"answer":"You have learned more about yourself and the world","explanation_fr":"La révision peut être le résultat de l'apprentissage."},{"type":"true_false","question":"Designing your future means controlling every event.","options":["True","False"],"answer":"False","explanation_fr":"Le texte reconnaît de nombreux facteurs extérieurs."},{"type":"true_false","question":"Repeated actions help shape the future.","options":["True","False"],"answer":"True","explanation_fr":"Les petites actions répétées participent à sa construction."},{"type":"open","question":"Which present choice could better support the future you want?","options":[],"answer":"I can reserve two regular periods for a useful skill and ask a knowledgeable person to review my direction with me.","explanation_fr":"La réponse doit relier une direction à un choix concret et révisable."}],"grammar":[{"point":"Instead of for an alternative","explanation_fr":"Instead of suivi d'un gérondif présente une autre manière de commencer.","example":"Instead of saying exactly where you must be, ask what direction you want."},{"point":"What clauses","explanation_fr":"What introduit ici le contenu de ce que vous choisissez.","example":"Choose what you practise, protect and pursue next."}],"discussion":["Which direction matters more than an exact job title?","What does your calendar say about your choices?","Who could help you review your future plan?"]},
  {"level":"B2","title":"Designing a Future Under Uncertainty","body":"Planning for the future requires a balance between direction and humility. Without direction, immediate demands can consume every available hour. Without humility, a plan can depend on predictions that circumstances will not respect. The aim is not to forecast every detail, but to make good choices while acknowledging uncertainty.\n\nOne useful approach is to distinguish commitments from options. A commitment is something you are willing to invest in now because it supports a valued direction. An option keeps a future possibility open. Learning a widely useful skill, maintaining relationships and protecting your health can support several possible futures rather than only one exact outcome.\n\nThis approach reduces the pressure to identify a single perfect path early. A student interested in both communication and technology does not necessarily have to choose a final profession immediately. A project involving writing, digital tools and user research could develop relevant abilities while revealing which activities are most satisfying.\n\nScenario thinking can also help. Instead of asking only what will happen if everything goes well, consider a smaller number of plausible situations: what if funding is delayed, the course is unavailable or family responsibilities increase? The purpose is not to imagine every disaster. It is to identify preparations that would make the plan less fragile.\n\nAt the same time, excessive preparation can become another form of uncertainty avoidance. You cannot remove every risk before acting. Decide which risks require protection, which require monitoring and which can be accepted. This makes action more deliberate without pretending that certainty is available.\n\nRegular review connects the plan to changing evidence. A direction may remain valuable while its timing changes. An opportunity may deserve attention even if it was absent from the original document. A fixed plan should not force you to ignore what you have learned.\n\nDesigning your future is therefore less like drawing a straight line and more like navigating. You choose a direction, build capabilities that remain useful across several routes, prepare for significant risks and adjust when the landscape changes. The plan gives purpose to your actions without demanding that the future obey it.","summary_fr":"Un plan d'avenir solide combine direction, compétences utiles dans plusieurs scénarios, préparation aux risques et révision. Il guide l'action sans prétendre prévoir ou contrôler chaque événement.","translation_fr":"Planifier l'avenir exige un équilibre entre direction et humilité. Sans direction, les demandes immédiates peuvent consommer chaque heure disponible. Sans humilité, un plan peut dépendre de prédictions que les circonstances ne respecteront pas. Le but n'est pas de prévoir chaque détail, mais de faire de bons choix tout en reconnaissant l'incertitude.\n\nUne approche utile distingue les engagements des options. Un engagement est quelque chose dans lequel vous acceptez d'investir maintenant parce qu'il soutient une direction valorisée. Une option garde une possibilité future ouverte. Apprendre une compétence largement utile, entretenir des relations et protéger sa santé peuvent soutenir plusieurs futurs possibles plutôt qu'un seul résultat exact.\n\nCette approche réduit la pression de choisir tôt un seul chemin parfait. Un étudiant intéressé à la fois par la communication et la technologie n'a pas nécessairement à choisir immédiatement une profession définitive. Un projet associant écriture, outils numériques et recherche utilisateur pourrait développer des capacités pertinentes tout en révélant quelles activités sont les plus satisfaisantes.\n\nLa réflexion par scénarios peut aussi aider. Au lieu de demander seulement ce qui arrivera si tout va bien, considérez un petit nombre de situations plausibles : et si le financement était retardé, le cours indisponible ou les responsabilités familiales plus importantes ? Le but n'est pas d'imaginer chaque catastrophe. Il est d'identifier les préparations qui rendraient le plan moins fragile.\n\nEn même temps, une préparation excessive peut devenir une autre façon d'éviter l'incertitude. Vous ne pouvez pas supprimer chaque risque avant d'agir. Décidez quels risques exigent une protection, lesquels demandent une surveillance et lesquels peuvent être acceptés. Cela rend l'action plus délibérée sans prétendre que la certitude est disponible.\n\nUn bilan régulier relie le plan aux preuves changeantes. Une direction peut rester valable tandis que son calendrier change. Une occasion peut mériter une attention même si elle était absente du document initial. Un plan fixe ne doit pas vous obliger à ignorer ce que vous avez appris.\n\nConcevoir votre avenir ressemble donc moins à tracer une ligne droite qu'à naviguer. Vous choisissez une direction, développez des capacités utiles sur plusieurs routes, préparez les risques importants et ajustez quand le paysage change. Le plan donne un sens à vos actions sans exiger que l'avenir lui obéisse.","knowledge_point":"L'apprenant découvre la planification par options et scénarios, la gestion différenciée des risques et l'ajustement régulier d'une direction.","vocabulary":[{"word":"humility","part_of_speech":"noun","translation_fr":"humilité","definition":"Recognising the limits of your knowledge or control.","example":"Planning requires direction and humility."},{"word":"forecast","part_of_speech":"verb","translation_fr":"prévoir","definition":"To say what you think will happen.","example":"The aim is not to forecast every detail."},{"word":"option","part_of_speech":"noun","translation_fr":"option","definition":"A possibility that remains available.","example":"An option keeps a future possibility open."},{"word":"scenario","part_of_speech":"noun","translation_fr":"scénario","definition":"A possible situation used to examine a plan.","example":"Scenario thinking tests the plan."},{"word":"plausible","part_of_speech":"adjective","translation_fr":"plausible","definition":"Reasonably possible or believable.","example":"Consider a few plausible situations."},{"word":"fragile","part_of_speech":"adjective","translation_fr":"fragile","definition":"Easily damaged or disrupted.","example":"Preparation makes the plan less fragile."},{"word":"monitor","part_of_speech":"verb","translation_fr":"surveiller","definition":"To observe something over time.","example":"Some risks require monitoring."},{"word":"navigate","part_of_speech":"verb","translation_fr":"naviguer, s'orienter","definition":"To find and adjust your route.","example":"Designing a future is like navigating."}],"questions":[{"type":"mcq","question":"What happens without humility in planning?","options":["The plan may depend on predictions circumstances reject","Immediate demands disappear","Every option closes","Risk becomes impossible"],"answer":"The plan may depend on predictions circumstances reject","explanation_fr":"L'humilité reconnaît les limites des prévisions."},{"type":"mcq","question":"What is an option?","options":["Something that keeps a future possibility open","A final commitment with no alternative","A prediction of every detail","A risk that must always be accepted"],"answer":"Something that keeps a future possibility open","explanation_fr":"L'option préserve une possibilité sans exiger un chemin unique."},{"type":"mcq","question":"Which investment can support several futures?","options":["Learning a widely useful skill","Choosing one exact outcome only","Ignoring relationships","Waiting for complete certainty"],"answer":"Learning a widely useful skill","explanation_fr":"Les compétences, relations et santé soutiennent plusieurs scénarios."},{"type":"mcq","question":"How can a combined project help the student?","options":["It develops abilities and reveals satisfying activities","It proves one profession is perfect immediately","It removes every future option","It guarantees funding"],"answer":"It develops abilities and reveals satisfying activities","explanation_fr":"Le projet sert à la fois l'apprentissage et l'exploration."},{"type":"mcq","question":"What is the purpose of scenario thinking?","options":["Identify preparations that make the plan less fragile","Imagine every possible disaster","Avoid all action","Prove the original plan is fixed"],"answer":"Identify preparations that make the plan less fragile","explanation_fr":"Quelques scénarios plausibles aident à préparer les difficultés."},{"type":"mcq","question":"How should risks be treated?","options":["Protect against some, monitor others and accept some","Eliminate every risk before acting","Ignore every risk","Treat all risks identically"],"answer":"Protect against some, monitor others and accept some","explanation_fr":"La réponse dépend de la nature et de l'importance du risque."},{"type":"mcq","question":"Why are regular reviews necessary?","options":["Evidence and opportunities can change","A fixed plan knows the future","Timing never changes","Learning should not affect action"],"answer":"Evidence and opportunities can change","explanation_fr":"Le plan doit intégrer les nouvelles informations."},{"type":"true_false","question":"A good plan requires the future to obey it.","options":["True","False"],"answer":"False","explanation_fr":"Le plan guide les actions sans contrôler l'avenir."},{"type":"true_false","question":"Designing the future is compared to navigating.","options":["True","False"],"answer":"True","explanation_fr":"La navigation illustre la direction et l'ajustement."},{"type":"open","question":"Name one capability and one scenario that could support a flexible future plan.","options":[],"answer":"I can develop clear writing for several careers and prepare a shorter study schedule in case family responsibilities increase.","explanation_fr":"La réponse doit associer une capacité polyvalente à une préparation pour un scénario plausible."}],"grammar":[{"point":"What if for scenarios","explanation_fr":"What if introduit une situation hypothétique à examiner.","example":"What if funding is delayed?"},{"point":"Less like more like","explanation_fr":"Cette comparaison remplace une métaphore par une autre plus adaptée.","example":"It is less like drawing a straight line and more like navigating."}],"discussion":["Which capability would remain useful across several futures?","Which plausible scenario should your plan include?","Which risk can you accept rather than eliminate?"]},
  {"level":"C1","title":"A Future Is a Portfolio of Choices","body":"People often speak about the future as though it were a destination selected once and then approached in a straight line. This metaphor can provide motivation, but it conceals the number of decisions that must be made when circumstances change. A more useful image may be a portfolio: a collection of capabilities, relationships, commitments and possibilities whose value does not depend on a single prediction.\n\nA portfolio approach does not mean pursuing everything simultaneously. Concentration remains necessary for developing excellence. It means examining whether your investments are so narrowly connected to one imagined outcome that a change would leave you without alternatives. Deep expertise can coexist with transferable abilities such as communication, judgment and collaboration.\n\nThis perspective also changes how we evaluate detours. An experience that does not lead directly to the preferred destination may still contribute knowledge, relationships or self-understanding. The value is not automatic, and disappointment should not be romanticised. The question is whether anything from the experience can be responsibly carried forward.\n\nHowever, adaptability has its own risks. Constantly preserving options can become a refusal to commit. Someone may attend introductory courses for years without accepting the demanding practice required for competence. A portfolio needs both exploration and concentration: periods for testing directions and periods for building depth.\n\nEthical commitments provide another form of continuity. Circumstances may alter a role or project, but principles concerning honesty, dignity and responsibility should not be revised merely because they become inconvenient. A flexible future plan is not one in which everything is negotiable. It distinguishes the route from the values that guide it.\n\nRegular reflection helps maintain this distinction. Which investments remain useful across several scenarios? Which commitment now deserves deeper attention? Which possibility should be closed because it consumes resources without serving a meaningful purpose? These questions prevent both rigidity and drift.\n\nDesigning a future is therefore not an attempt to make uncertainty disappear. It is the deliberate construction of a life that can remain purposeful while conditions change. You choose where to deepen your abilities, where to preserve options and which principles will continue to guide you, even when the original map no longer matches the territory.","summary_fr":"L'avenir peut être conçu comme un portefeuille de capacités, relations et engagements. Il faut équilibrer exploration et approfondissement, tirer des leçons des détours et garder des principes stables malgré les changements.","translation_fr":"Les gens parlent souvent de l'avenir comme s'il s'agissait d'une destination choisie une fois puis approchée en ligne droite. Cette métaphore peut motiver, mais elle cache le nombre de décisions nécessaires quand les circonstances changent. Une image plus utile pourrait être un portefeuille : un ensemble de capacités, de relations, d'engagements et de possibilités dont la valeur ne dépend pas d'une seule prédiction.\n\nUne approche en portefeuille ne signifie pas poursuivre tout simultanément. La concentration reste nécessaire pour développer l'excellence. Elle consiste à examiner si vos investissements sont si étroitement liés à un seul résultat imaginé qu'un changement vous laisserait sans alternative. Une expertise approfondie peut coexister avec des capacités transférables comme la communication, le jugement et la collaboration.\n\nCette perspective change aussi notre évaluation des détours. Une expérience qui ne mène pas directement à la destination préférée peut néanmoins apporter des connaissances, des relations ou une meilleure connaissance de soi. Cette valeur n'est pas automatique et la déception ne doit pas être idéalisée. La question est de savoir si quelque chose de cette expérience peut être responsablement conservé pour la suite.\n\nCependant, l'adaptabilité comporte ses propres risques. Préserver constamment des options peut devenir un refus de s'engager. Quelqu'un peut suivre des cours d'introduction pendant des années sans accepter la pratique exigeante nécessaire pour acquérir une compétence. Un portefeuille a besoin d'exploration et de concentration : des périodes pour tester des directions et des périodes pour construire la profondeur.\n\nLes engagements éthiques offrent une autre forme de continuité. Les circonstances peuvent modifier un rôle ou un projet, mais les principes d'honnêteté, de dignité et de responsabilité ne devraient pas être révisés simplement parce qu'ils deviennent incommodes. Un plan d'avenir flexible n'est pas un plan où tout est négociable. Il distingue le chemin des valeurs qui le guident.\n\nUne réflexion régulière aide à maintenir cette distinction. Quels investissements restent utiles dans plusieurs scénarios ? Quel engagement mérite maintenant une attention plus profonde ? Quelle possibilité devrait être fermée parce qu'elle consomme des ressources sans servir un but significatif ? Ces questions empêchent à la fois la rigidité et la dérive.\n\nConcevoir un avenir n'est donc pas une tentative de faire disparaître l'incertitude. C'est la construction délibérée d'une vie capable de rester porteuse de sens pendant que les conditions changent. Vous choisissez où approfondir vos capacités, où préserver des options et quels principes continueront à vous guider, même lorsque la carte originale ne correspond plus au territoire.","knowledge_point":"L'apprenant conçoit une trajectoire adaptable qui équilibre expertise, options, apprentissage des détours et principes éthiques stables.","vocabulary":[{"word":"portfolio","part_of_speech":"noun","translation_fr":"portefeuille","definition":"A collection of related investments or achievements.","example":"A future can be viewed as a portfolio."},{"word":"transferable","part_of_speech":"adjective","translation_fr":"transférable","definition":"Useful in different situations or roles.","example":"Communication is a transferable ability."},{"word":"detour","part_of_speech":"noun","translation_fr":"détour","definition":"An indirect route away from the expected path.","example":"A detour may still contribute knowledge."},{"word":"romanticise","part_of_speech":"verb","translation_fr":"idéaliser","definition":"To make something seem better than it really is.","example":"Disappointment should not be romanticised."},{"word":"adaptability","part_of_speech":"noun","translation_fr":"adaptabilité","definition":"The ability to adjust to new conditions.","example":"Adaptability has its own risks."},{"word":"depth","part_of_speech":"noun","translation_fr":"profondeur","definition":"A strong and detailed level of knowledge or skill.","example":"Some periods build depth."},{"word":"negotiable","part_of_speech":"adjective","translation_fr":"négociable","definition":"Open to discussion or change.","example":"Not every principle is negotiable."},{"word":"drift","part_of_speech":"noun","translation_fr":"dérive","definition":"Gradual movement without a clear direction.","example":"Reflection prevents rigidity and drift."}],"questions":[{"type":"mcq","question":"What does the straight-line metaphor conceal?","options":["The decisions needed when circumstances change","The value of motivation","The existence of destinations","The need for expertise"],"answer":"The decisions needed when circumstances change","explanation_fr":"Une trajectoire réelle exige des décisions et des ajustements."},{"type":"mcq","question":"What can a future portfolio contain?","options":["Capabilities, relationships, commitments and possibilities","Only one exact prediction","Introductory courses only","No commitments"],"answer":"Capabilities, relationships, commitments and possibilities","explanation_fr":"Ces quatre éléments composent l'image du portefeuille."},{"type":"mcq","question":"Can deep expertise coexist with transferable abilities?","options":["Yes, they can support each other","No, expertise prevents communication","Only if every option remains open","Only without concentration"],"answer":"Yes, they can support each other","explanation_fr":"Le texte associe expertise et compétences transférables."},{"type":"mcq","question":"How should a detour be evaluated?","options":["Ask what can responsibly be carried forward","Assume every disappointment is valuable","Treat it as automatic success","Ignore its actual cost"],"answer":"Ask what can responsibly be carried forward","explanation_fr":"La valeur doit être examinée sans idéaliser la déception."},{"type":"mcq","question":"What risk comes from constantly preserving options?","options":["It can become a refusal to commit","It always builds deep competence","It closes every possibility","It guarantees a meaningful purpose"],"answer":"It can become a refusal to commit","explanation_fr":"Explorer sans s'engager peut empêcher le développement réel."},{"type":"mcq","question":"What balance does a portfolio need?","options":["Exploration and concentration","Rigidity and drift","Prediction and control","Disappointment and avoidance"],"answer":"Exploration and concentration","explanation_fr":"Des périodes de test et d'approfondissement sont nécessaires."},{"type":"mcq","question":"Which principles should remain stable?","options":["Honesty, dignity and responsibility","Every route and role","Each introductory course","All original predictions"],"answer":"Honesty, dignity and responsibility","explanation_fr":"Les routes changent, mais ces valeurs ne doivent pas être abandonnées par commodité."},{"type":"true_false","question":"A flexible plan makes every value negotiable.","options":["True","False"],"answer":"False","explanation_fr":"La flexibilité concerne le chemin, pas toutes les valeurs."},{"type":"true_false","question":"Regular reflection can prevent both rigidity and drift.","options":["True","False"],"answer":"True","explanation_fr":"Les questions de bilan évitent ces deux extrêmes."},{"type":"open","question":"Which ability will you deepen, which option will you preserve and which principle will guide you?","options":[],"answer":"I will deepen professional writing, preserve digital learning as an option and keep honesty as a principle when my route changes.","explanation_fr":"La réponse doit distinguer approfondissement, option et principe stable."}],"grammar":[{"point":"As though for metaphor","explanation_fr":"As though présente une manière de voir qui ne correspond pas nécessairement à la réalité.","example":"People speak about the future as though it were a destination selected once."},{"point":"Not in but in for contrast","explanation_fr":"Cette construction refuse une définition avant d'en proposer une autre.","example":"Designing a future is not an attempt to remove uncertainty, but the construction of a purposeful life."}],"discussion":["Which transferable ability belongs in your future portfolio?","When should exploration give way to deeper commitment?","Which principle should remain stable when your plans change?"]}
 ]$content$::jsonb) as x(level public.rw_level,title text,body text,summary_fr text,translation_fr text,knowledge_point text,vocabulary jsonb,questions jsonb,grammar jsonb,discussion jsonb)
)
insert into public.rw_lessons(session_id,level,title,body,word_count,summary_fr,translation_fr,knowledge_point,vocabulary,questions,grammar,discussion,mention,status,content_type,rights_status,published_at)
select s.id,c.level,c.title,c.body,cardinality(regexp_split_to_array(btrim(c.body),'[[:space:]]+')),
 c.summary_fr,c.translation_fr,c.knowledge_point,c.vocabulary,c.questions,c.grammar,c.discussion,
 'original','published','original text','Texte original OpenDoorsClass',now()
from content c join public.rw_weeks w on w.week_number=4 join public.rw_sessions s on s.week_id=w.id and s.day_index=6
on conflict(session_id,level) do update set title=excluded.title,body=excluded.body,word_count=excluded.word_count,
 summary_fr=excluded.summary_fr,translation_fr=excluded.translation_fr,knowledge_point=excluded.knowledge_point,
 vocabulary=excluded.vocabulary,questions=excluded.questions,grammar=excluded.grammar,discussion=excluded.discussion,
 mention='original',status='published',content_type='original text',rights_status='Texte original OpenDoorsClass',
 published_at=coalesce(rw_lessons.published_at,now()) where rw_lessons.status<>'published';
do $$ declare invalid_count integer; begin
 select count(*) into invalid_count from public.rw_lessons l join public.rw_sessions s on s.id=l.session_id
 join public.rw_weeks w on w.id=s.week_id where w.week_number=4 and s.day_index=6 and
 (l.status<>'published' or jsonb_array_length(l.questions)<>10 or jsonb_array_length(l.vocabulary)<8
 or jsonb_array_length(l.grammar)<>2 or jsonb_array_length(l.discussion)<>3 or l.body='' or coalesce(l.translation_fr,'')='');
 if invalid_count<>0 then raise exception 'Validation impossible: % leçons incomplètes',invalid_count; end if;
end $$;